$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$wrapper = Decode ""

$routePath = Join-Path $root "app\api\market\requests\[id]\group-booking\route.ts"
$migrationDir = Join-Path $root "supabase\migrations"

if (-not (Test-Path -LiteralPath $routePath)) {
    throw "12.97 : route group-booking introuvable."
}

$route = [System.IO.File]::ReadAllText($routePath)

if (-not ($route.Contains("KLYX_GROUP_BOOKING_CREATE_12_85") -or $route.Contains("klyx_create_multi_slot_booking_group"))) {
    throw "12.97 : architecture Group Booking 12.85 introuvable."
}

$migration96 = Get-ChildItem -LiteralPath $migrationDir -File | Select-String -Pattern "KLYX_GROUP_ATOMIC_LIVE_COVERAGE_12_96" -SimpleMatch -List

if (-not $migration96) {
    throw "12.97 : migration atomique 12.96 introuvable."
}

if (-not $route.Contains("KLYX_GROUP_STALE_PROVIDER_RECOVERY_12_97")) {
    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

    Copy-Item -LiteralPath $routePath -Destination ($routePath + ".bak-12-97-" + $timestamp) -Force

    if (-not $route.Contains("NextResponse")) {
        throw "12.97 : NextResponse introuvable dans group-booking."
    }

    if (-not $route.Contains("getAuthenticatedProfile")) {
        throw "12.97 : getAuthenticatedProfile introuvable dans group-booking."
    }

    if (-not $route.Contains("supabaseAdmin")) {
        throw "12.97 : supabaseAdmin introuvable dans group-booking."
    }

    $postRegex = [regex]'export\s+async\s+function\s+POST\s*\('
    $matches = $postRegex.Matches($route)

    if ($matches.Count -ne 1) {
        throw "12.97 : exactement un export POST etait attendu avant patch. Trouve : $($matches.Count)"
    }

    $route = $postRegex.Replace($route, "async function klyxGroupBookingPostBeforeRecovery(", 1)

    $route = $route.TrimEnd() + "`r`n`r`n" + $wrapper.TrimStart() + "`r`n"

    [System.IO.File]::WriteAllText($routePath, $route, $utf8)
}

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.97 APPLIQUE"
Write-Host "======================================"
Write-Host "Blocage atomique 12.96 : INTERCEPTE"
Write-Host "Erreur 500 opaque : EVITEE"
Write-Host "Candidat stale : RESYNCHRONISE"
Write-Host "Offre commerciale : CONSERVEE"
Write-Host "Demande client : CONSERVEE"
Write-Host "Booking enfant apres echec : 0"
Write-Host "Paiement apres echec : 0"
Write-Host "Choix autre prestataire : POSSIBLE"
Write-Host "======================================"
Write-Host ""
